def digit_root(n):
    if n == 0:
        return 0
    elif n % 9 == 0:
        return 9
    else:
        return n % 9

def final_single_digit_sum(M, blocks):
    total_sum = 0
    for length, digit in blocks:
        total_sum += length * digit

    return digit_root(total_sum)

def main():
    T = int(input().strip())
    results = []
    for _ in range(T):
        M = int(input().strip())
        blocks = []
        for _ in range(M):
            length, digit = map(int, input().strip().split())
            blocks.append((length, digit))
        results.append(final_single_digit_sum(M, blocks))

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
```

